cat > /tmp/arb_div_probe_fixed.c <<'C'
#include <stdio.h>
#include <flint/flint.h>
#include <flint/arb.h>

static void print_arb(const char *name, arb_t z){
    printf("%s: ", name);
    if (arb_is_nan(z)) { printf("nan\n"); }
    else if (!arb_is_finite(z)) { printf("inf\n"); }
    else if (arb_is_zero(z)) { printf("zero\n"); }
    else {
        // midpoint as double for readability; also report mag
        double mid = arb_get_d(midref(z), 0);
        // arb_get_d requires proper init; keep it simple: use arb_get_d on mid
    }
}

int main(){
    slong prec = 100000;
    arb_t x,y,z,eps;
    arb_init(x); arb_init(y); arb_init(z); arb_init(eps);

    // Case 1: x = 0 (mid=0, rad=0)
    arb_zero(x);
    // y = 1/3 = arb_inv(3,3)
    arb_set_ui(y, 3);
    arb_inv(y, y, prec);
    arb_div(z, x, y, prec);
    int case1_nan = arb_is_nan(z);
    int case1_finite = arb_is_finite(z);
    int case1_zero = arb_is_zero(z);
    printf("case1_finite=%d zero=%d nan=%d\n", case1_finite, case1_zero, case1_nan);

    // Case 2: x = [0 +/- eps] with eps = 1e-10
    arb_midref(x);
    arb_zero(x);
    arb_set_d(arb_radref(x), 1e-10);
    arb_set_ui(y, 3);
    arb_inv(y, y, prec);
    // ensure y has zero radius as in report by zeroing rad
    mag_zero(arb_radref(y));

    arb_div(z, x, y, prec);
    int case2_finite = arb_is_finite(z);
    int case2_nan = arb_is_nan(z);
    int case2_zero = arb_is_zero(z);
    printf("case2_finite=%d zero=%d nan=%d\n", case2_finite, case2_zero, case2_nan);

    arb_clear(x); arb_clear(y); arb_clear(z); arb_clear(eps);
    return 0;
}
C

# compile using flint-config if available; otherwise try pkg-config / standard include/lib paths
cd /workspace/fixed
