fi

gcc -O2 -std=c11 /tmp/arb_div_probe_fixed.c $FLINT_CFLAGS $FLINT_LIBS -o /tmp/arb_div_probe_fixed -Wl,-rpath,/workspace/fixed/src

/tmp/arb_div_probe_fixed | tee /tmp/arb_div_probe_fixed.out

